const daftarTopik = [
  'KESELAMATAN KERJA — APAR & Kesiapsiagaan Kebakaran Gedung (jenis APAR, teknik PASS, titik penempatan, inspeksi rutin)',
  'KEAMANAN — SOP Patroli Satpam & Serah Terima Shift (jadwal patroli, titik kontrol, buku mutasi, laporan temuan)',
  'KESELAMATAN KERJA — Instalasi Listrik & Panel Gedung (kabel terkelupas, stop kontak bertumpuk, LOTO, panel terkunci)',
  'KESELAMATAN KERJA — Bekerja di Ketinggian (perawatan AC, penggantian lampu, rooftop, tangga & body harness)',
  'KESELAMATAN KERJA — Ruang Genset & Ruang Terbatas (gas buang, ventilasi, kebisingan, prosedur confined space)',
  'KESELAMATAN KERJA — Housekeeping 5R & Pencegahan Terpeleset/Tersandung/Terjatuh (lantai basah, kabel melintang)',
  'KESELAMATAN KERJA — Alat Pelindung Diri untuk Teknisi & Vendor (helm, sepatu safety, rompi, sarung tangan, kacamata)',
  'KESELAMATAN KERJA — Keselamatan Lift & Prosedur Saat Terjebak di Dalam Lift (jangan panik, tombol darurat, tunggu teknisi)',

  'KESEHATAN KERJA — Ergonomi & Postur Kerja di Meja Kantor (posisi duduk, tinggi monitor, sandaran, peregangan berkala)',
  'KESEHATAN KERJA — Kesehatan Mata & Kelelahan Digital (aturan 20-20-20, pencahayaan, silau layar)',
  'KESEHATAN KERJA — Kualitas Udara Dalam Ruangan & Perawatan HVAC (filter AC, sirkulasi udara, jamur, bau)',
  'KESEHATAN KERJA — Kebersihan Pantry, Air Minum & Keamanan Pangan (dispenser, kulkas bersama, makanan basi)',
  'KESEHATAN KERJA — Kesehatan Mental & Manajemen Stres Kerja (beban kerja, istirahat, tanda kelelahan, minta bantuan)',
  'KESEHATAN KERJA — Kebisingan & Perlindungan Pendengaran di Area Mesin/Genset (ear plug, durasi paparan)',
  'KESEHATAN KERJA — Bahan Kimia Pembersih & Sanitasi (MSDS, pelabelan, jangan mencampur, ventilasi, sarung tangan)',
  'KESEHATAN KERJA — P3K, Kotak Obat & Penanganan Cedera Ringan/Pingsan (isi kotak P3K, langkah awal, siapa dihubungi)',

  'KEAMANAN — Pemantauan CCTV & Pelaporan Anomali (blind spot, pengecekan rekaman, eskalasi temuan)',
  'KEAMANAN — Pengendalian Akses Tamu, Vendor & Area Terbatas (buku tamu, kartu identitas, pendampingan, tailgating)',
  'KEAMANAN — Pengamanan Kunci, Aset & Ruang Vital (ruang server, panel, brankas, serah terima kunci)',
  'KEAMANAN — Kewaspadaan Orang Asing & Social Engineering (modus penipuan, vendor palsu, mengaku petugas)',
  'KEAMANAN — Keamanan Kendaraan & Area Parkir (kunci ganda, barang berharga di kabin, pengawasan area)',
  'KEAMANAN — Clean Desk & Keamanan Data di Lingkungan Kerja (dokumen tertinggal, layar terbuka, badge, print-an)',
  'KEAMANAN — Tanggap Darurat & Pelaporan Insiden (rantai komando, nomor darurat, kronologi laporan yang benar)',
  'KEAMANAN — Keselamatan Berkendara & Perjalanan Dinas (kelelahan menyetir, helm, sabuk pengaman, cek kendaraan)'
];

const daftarGaya = [
  'CHECKLIST HARIAN — sajikan sebagai daftar tindakan konkret yang bisa langsung dicek dan dikerjakan hari ini.',
  'STUDI KASUS SINGKAT — hook berisi satu skenario insiden yang masuk akal di gedung perkantoran; kelima poin berisi pelajaran yang ditarik darinya.',
  'MITOS vs FAKTA — tiap poin membongkar satu anggapan keliru yang umum, lalu meluruskannya.',
  'DO & DON\'T — tiap poin tegas menyatakan apa yang harus dipastikan atau apa yang harus dihindari.',
  'DAMPAK & KONSEKUENSI — tiap poin menjelaskan akibat nyata bila diabaikan, dari sudut pandang yang berbeda-beda.'
];

const cfg = $('Konfigurasi').first().json;
const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 0);
const dayOfYear = Math.floor((now - startOfYear) / 86400000);

const ov = cfg.overrideIndex;
const pakaiOverride = ov !== '' && ov !== null && ov !== undefined && !isNaN(Number(ov));
const idx = pakaiOverride ? Number(ov) : dayOfYear;

const topikTerpilih = daftarTopik[idx % daftarTopik.length];
const gayaTerpilih = daftarGaya[idx % daftarGaya.length];
const pilar = topikTerpilih.split('—')[0].trim();
const labelGaya = gayaTerpilih.split('—')[0].trim();
const tanggalHariIni = now.toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

return [{ json: { topikTerpilih, gayaTerpilih, pilar, labelGaya, tanggalHariIni, idx, pakaiOverride } }];

const m = $('Parse Materi JSON').first().json.materi;
const info = $('Pilih Topik Hari Ini').first().json;
const cfg = $('Konfigurasi').first().json;

const ikonPilar = {
  'KESELAMATAN KERJA': '🦺',
  'KESEHATAN KERJA': '🩺',
  'KEAMANAN': '🛡️'
};

const ikonPoin = {
  'CHECKLIST HARIAN': '☑️',
  'STUDI KASUS SINGKAT': '•',
  'MITOS vs FAKTA': '🔎',
  "DO & DON'T": '•',
  'DAMPAK & KONSEKUENSI': '⚠️'
};

const rapiGaya = (s) => s.toLowerCase().replace(/(^|\s)\S/g, (c) => c.toUpperCase());

const b = ikonPoin[info.labelGaya] || '•';
const poin = (m.poin || []).map((p) => b + '  ' + p).join('\n\n');

const pesanFinal =
  (ikonPilar[info.pilar] || '📌') + ' *' + info.pilar + '*  ·  ' + rapiGaya(info.labelGaya) + '\n' +
  info.tanggalHariIni + '\n\n' +
  '*' + m.judul + '*\n' +
  m.hook + '\n\n' +
  poin + '\n\n' +
  '📌 ' + m.aksi;

return [{ json: { targetGrup: cfg.targetGrup, pesanFinal } }];
